-- G20: bounded private candidate generation with immutable provenance and telemetry.
create table public.contract_generation_runs(id uuid primary key default gen_random_uuid(),contract_id uuid not null references public.generation_contracts(id) on delete restrict,reuse_decision_id uuid not null references public.contract_reuse_decisions(id) on delete restrict,idempotency_key text unique not null,provider text not null,model text not null,prompt_version text not null,candidate_count integer not null check(candidate_count between 2 and 5),timeout_ms integer not null check(timeout_ms between 1000 and 120000),maximum_attempts integer not null check(maximum_attempts between 1 and 5),status text not null check(status in('queued','running','generated','failed','cancelled')),failure_payload jsonb not null default '[]',input_tokens integer not null default 0,output_tokens integer not null default 0,cost_usd numeric not null default 0,latency_ms integer,created_at timestamptz not null default now(),completed_at timestamptz);
create table public.contract_generation_candidates(id uuid primary key default gen_random_uuid(),generation_run_id uuid not null references public.contract_generation_runs(id) on delete restrict,contract_id uuid not null references public.generation_contracts(id) on delete restrict,candidate_index integer not null check(candidate_index>=0),candidate_payload jsonb not null,status text not null default 'pending_qa' check(status in('pending_qa','qa_running','qa_failed','qa_passed','human_review','accepted','rejected')),student_visible boolean not null default false check(student_visible=false),prompt_version text not null,provider text not null,model text not null,provider_request_id text,taxonomy_release_id uuid not null references public.taxonomy_releases(id) on delete restrict,lexical_release_id uuid not null references public.lexical_releases(id) on delete restrict,idempotency_key text unique not null,attempt integer not null check(attempt>0),created_at timestamptz not null default now(),unique(generation_run_id,candidate_index));
create or replace function public.prevent_generation_candidate_mutation()returns trigger language plpgsql as $$begin if old.candidate_payload<>new.candidate_payload or old.contract_id<>new.contract_id or old.generation_run_id<>new.generation_run_id then raise exception 'generation_candidate_content_is_immutable';end if;if new.student_visible then raise exception 'generation_candidate_not_student_visible';end if;return new;end$$;create trigger immutable_generation_candidate before update on public.contract_generation_candidates for each row execute function public.prevent_generation_candidate_mutation();
alter table public.contract_generation_runs enable row level security;alter table public.contract_generation_candidates enable row level security;create policy generation_runs_staff_read on public.contract_generation_runs for select using(public.is_staff());create policy generation_candidates_staff_read on public.contract_generation_candidates for select using(public.is_staff());grant select on public.contract_generation_runs,public.contract_generation_candidates to authenticated;
comment on table public.contract_generation_candidates is 'Private immutable candidate content. Status transitions enable QA/review, but candidates are never directly student-visible.';
